import fs from "node:fs/promises";
import path from "node:path";
import Link from "next/link";
import { notFound } from "next/navigation";
import { renderMarkdown } from "@/lib/markdown";

/** The full validation reports, as generated by `npm run validate:*`, readable on the site. */
const REPORTS = {
  speech: { file: "speech-report.md", title: "Speech measurement report" },
  camera: { file: "camera-report.md", title: "Camera signal report" },
} as const;
type ReportId = keyof typeof REPORTS;

export const dynamicParams = false;
export function generateStaticParams() {
  return Object.keys(REPORTS).map((report) => ({ report }));
}

export async function generateMetadata({ params }: { params: Promise<{ report: string }> }) {
  const { report } = await params;
  return { title: REPORTS[report as ReportId]?.title ?? "Report" };
}

export default async function ReportPage({ params }: { params: Promise<{ report: string }> }) {
  const { report } = await params;
  const entry = REPORTS[report as ReportId];
  if (!entry) notFound();
  const source = await fs.readFile(path.join(process.cwd(), "docs", "validation", entry.file), "utf8").catch(() => null);
  if (!source) notFound();
  return (
    <main id="content" tabIndex={-1} className="frame pb-section pt-[calc(var(--header-h)+var(--spacing-hero))] focus:outline-none">
      <p className="text-ui"><Link href="/trust" className="text-fg-muted underline decoration-1 underline-offset-text hover:text-fg">How accurate is the feedback?</Link></p>
      <p className="mt-2 text-meta text-fg-subtle">Preliminary: synthetic voices and faces, not yet validated with real people.</p>
      <article className="mt-8 max-w-column text-body text-fg-muted">{renderMarkdown(source)}</article>
    </main>
  );
}
